import{K as r,a as i,c as l,b as t,k as n,q as c,ac as h}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"PowerPoint 表格、图表与 Excel 数据关联","description":"选择原生图表、嵌入工作簿、链接源文件或静态图片，控制源数据更新、图表标注、敏感数据和演示稿交付稳定性。","frontmatter":{"title":"PowerPoint 表格、图表与 Excel 数据关联","description":"选择原生图表、嵌入工作簿、链接源文件或静态图片，控制源数据更新、图表标注、敏感数据和演示稿交付稳定性。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · PowerPoint 演示制作","summary":"选择原生图表、嵌入工作簿、链接源文件或静态图片，控制源数据更新、图表标注、敏感数据和演示稿交付稳定性。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"PowerPoint 图片、图形与流程图排版","link":"/tools/office/powerpoint/graphics"},"next":{"text":"PowerPoint 动画、切换与媒体","link":"/tools/office/powerpoint/animation"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"PowerPoint 图片、图形与流程图排版","link":"/tools/office/powerpoint/graphics"},"next":{"text":"PowerPoint 动画、切换与媒体","link":"/tools/office/powerpoint/animation"}},"headers":[],"relativePath":"tools/office/powerpoint/data.md","filePath":"tools/office/powerpoint/data.md"}'),s={name:"tools/office/powerpoint/data.md"},k=Object.assign(s,{setup(d){const a={path:"/tools/office/powerpoint/data",app:"PowerPoint",title:"把 Excel 结果变成可靠的演示图表",steps:[{tab:"插入",command:"图表",setting:"簇状柱形图；部门：运营、技术",anchor:"walkthrough-1"},{tab:"图表设计",command:"添加图表元素",setting:"标题：十月已完成金额；单位：元",anchor:"walkthrough-2"},{tab:"文件",command:"导出",setting:"PDF 阅读版；检查隐藏工作簿数据",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=t("h1",{id:"powerpoint-表格、图表与-excel-数据关联",tabindex:"-1"},[n("PowerPoint 表格、图表与 Excel 数据关联 "),t("a",{class:"header-anchor",href:"#powerpoint-表格、图表与-excel-数据关联","aria-label":'Permalink to "PowerPoint 表格、图表与 Excel 数据关联"'},"​")],-1)),e[1]||(e[1]=t("p",null,"数据页的目标是让听众看清比较对象、数量级和结论。通常只保留支撑本页结论的数据，把完整明细留在附录或对应工作簿中。",-1)),c(o,{guide:a}),e[2]||(e[2]=h('<h2 id="choose" tabindex="-1">表格还是图表 <a class="header-anchor" href="#choose" aria-label="Permalink to &quot;表格还是图表 {#choose}&quot;">​</a></h2><p>需要逐项查精确数值时使用表格；需要比较大小、展示趋势或分布时使用图表。不要把 Excel 整张工作表截图塞进一页，列名和数字很可能在投影后无法辨认。</p><p>以<a href="/tools/office/excel/project">月报练习</a>为例，“10 月已完成金额按部门分布”适合两根柱子的图表，运营 2440、技术 720；财务没有符合条件的记录，可按报告约定显示零并注明口径。</p><h2 id="chart" tabindex="-1">原生图表的操作 <a class="header-anchor" href="#chart" aria-label="Permalink to &quot;原生图表的操作 {#chart}&quot;">​</a></h2><p>通过“插入 → 图表”选择簇状柱形图，在打开的数据编辑表中只保留需要的类别和系列。修改图表标题、坐标轴单位和数据标签，删除无意义的默认系列名称。多系列图应有清楚图例，单系列可减少重复装饰。</p><p>如果图形数字不对，先检查编辑数据范围，再检查隐藏行列和系列设置。图表本身不能判断源数字是否来自正确的月份和状态，口径仍需人工核实。</p><h2 id="paste" tabindex="-1">从 Excel 粘贴的选择 <a class="header-anchor" href="#paste" aria-label="Permalink to &quot;从 Excel 粘贴的选择 {#paste}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适合场景</th><th>代价或检查项</th></tr></thead><tbody><tr><td>嵌入工作簿</td><td>希望在 PPT 内继续编辑数据</td><td>文件变大，检查嵌入的数据是否超出展示范围</td></tr><tr><td>链接 Excel 数据</td><td>同一团队持续更新报告</td><td>依赖源文件位置、权限和更新状态</td></tr><tr><td>图片</td><td>需要稳定呈现、无需继续计算</td><td>数字不能直接编辑，必须在源表更新后重新导出</td></tr><tr><td>原生表格</td><td>少量精确数据</td><td>需要维护一致格式和更新流程</td></tr></tbody></table><p>复制 Excel 图表后，在 PowerPoint 粘贴选项中选择相应方式。不要只点默认粘贴就假定结果会自动更新。复制为图片的图表不再连接源数据；嵌入的数据也不是原工作簿的实时镜像。</p><h2 id="links" tabindex="-1">链接更新与交付 <a class="header-anchor" href="#links" aria-label="Permalink to &quot;链接更新与交付 {#links}&quot;">​</a></h2><p>使用链接时，把源工作簿与演示稿纳入约定的目录或共享位置，记录文件名和工作表。源数据变化后检查链接更新结果，逐个核对关键指标；文件移动、路径变化或权限不足都可能让更新失败。</p><p>准备交付固定版本时，可以保留可编辑工作稿，再单独制作静态交付副本。断开链接通常会改变后续更新能力，操作前保留源稿，断开后实际打开并检查图表。不要只因为当前电脑显示了缓存数据就认定收件人也能完整更新。</p><h2 id="labels" tabindex="-1">标注与敏感数据 <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;标注与敏感数据 {#labels}&quot;">​</a></h2><p>图表页至少写明时间范围、单位和必要条件，例如“2026 年 10 月，状态为已完成，金额单位：元，虚构练习数据”。数字四舍五入后分项可能不严格加总到总计，需要保留解释；不能为了让总和凑齐随意修改原值。</p><p>嵌入工作簿可能包含比画面更多的数据。外发时打开嵌入对象检查，不只看当前可见图表。隐藏行、隐藏页、演讲备注和批注同样可能带出未准备分享的信息。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>把同一张 Excel 图表分别以链接和图片方式放入两页。修改源数据后更新链接，链接图应按实际更新流程变化，图片仍保持原样。再移动演示副本到另一目录或目标电脑，检查外部依赖，明确最终交付采用哪一种方式。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把 Excel 结果变成可靠的演示图表 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把 Excel 结果变成可靠的演示图表 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：建立原生图表 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：建立原生图表 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 图表。</strong></p><p>点击“插入 → 图表”选择簇状柱形图，在弹出的数据编辑表中填运营 2440、技术 720，删除不需要的默认系列。关闭数据窗口后核对柱高、分类和图例。金额来自十月已完成订单，不能把全部月份的技术 1620 混进同一张图。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让图表脱离讲解也可读 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让图表脱离讲解也可读 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：图表设计 → 添加图表元素。</strong></p><p>添加清楚的数据标签和单位，注明状态条件与日期范围。轴和标签只保留需要的信息，避免图表缩小后被装饰遮盖。若从 Excel 粘贴，先决定嵌入、链接还是图片：三种方式的更新能力、可编辑性与外发数据范围不同。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：核对交付的图形与数据 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：核对交付的图形与数据 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>重新打开图表的数据编辑窗口，确认没有多余敏感行或旧系列。用最终版本导出 PDF，核对数值、字体和坐标轴是否完整；如果交付 PPTX，接收方可能继续编辑内嵌数据，不能把屏幕上只看见两根柱子当成只包含两个数字。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>链接图表依赖源文件位置和访问权限。移动文件夹或换电脑后应实际更新一次并核对；没有可靠更新条件时，可选择明确标注截止时间的静态交付版本。</p>',30))])}}});export{u as __pageData,k as default};
